<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/db.php';
requireRole(['administrator']);
$conn = db();
$requests = $conn->query("SELECT m.id,m.title,m.description,m.priority,m.status,m.created_at,u.username AS reported_by FROM maintenance_requests m JOIN users u ON u.id=m.user_id ORDER BY FIELD(m.status,'pending','in_progress','resolved'),m.created_at DESC")->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maintenance | CourtIQ</title><link rel="stylesheet" href="<?= projectUrl('assets/css/style.css') ?>"></head>
<body class="dashboard-layout admin-dashboard"><?php require __DIR__ . '/partials/nav.php'; ?><main class="dashboard-content-main container admin-main">
<?php if (!empty($_GET['error'])): ?><div class="admin-alert is-error"><?= e($_GET['error']) ?></div><?php endif; ?><?php if (!empty($_GET['success'])): ?><div class="admin-alert is-success">Maintenance status saved.</div><?php endif; ?>
<section class="admin-page-heading"><div><span class="admin-eyebrow">SERVICE DESK</span><h1>Maintenance requests</h1><p>Review every issue raised by residents and keep its status current.</p></div><a class="btn btn-primary" href="residents.php">View residents</a></section>
<section class="admin-section"><div class="admin-section-heading"><div><h2>Issue register</h2><p>Pending, confirmed/in progress and solved issues are listed here.</p></div><span class="admin-count"><?= count($requests) ?> records</span></div><div class="admin-table-wrap"><table class="dash-table admin-table"><thead><tr><th>Issue</th><th>Reported by</th><th>Priority</th><th>Current status</th><th>Update status</th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><strong><?= e($request['title']) ?></strong><small><?= e($request['description']) ?></small></td><td><?= e($request['reported_by']) ?><small><?= date('M j, Y', strtotime($request['created_at'])) ?></small></td><td><span class="priority-<?= e($request['priority']) ?>"><?= ucfirst(e($request['priority'])) ?></span></td><td><span class="status-pill status-<?= e($request['status']) ?>"><?= str_replace('_',' ',ucfirst(e($request['status']))) ?></span></td><td><form method="post" action="actions.php" class="inline-form"><?= csrfField() ?><input type="hidden" name="action" value="maintenance_status"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><select name="status"><option value="pending" <?= $request['status']==='pending'?'selected':'' ?>>Pending</option><option value="in_progress" <?= $request['status']==='in_progress'?'selected':'' ?>>Confirmed / in progress</option><option value="resolved" <?= $request['status']==='resolved'?'selected':'' ?>>Solved</option></select><button class="btn btn-secondary btn-sm">Save</button></form></td></tr><?php endforeach; ?><?php if (!$requests): ?><tr><td colspan="5" class="admin-empty">No maintenance requests have been raised.</td></tr><?php endif; ?></tbody></table></div></section>
</main></body></html>
